<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><section class="sd-profile-section"><h2><?php esc_html_e( 'Public activity', 'social-discovery' ); ?></h2><?php if ( function_exists( 'bp_activity_get' ) ) : $activities = bp_activity_get( array( 'user_id' => $args['user']->ID, 'per_page' => 5, 'page' => 1, 'scope' => 'public', 'display_comments' => false, 'show_hidden' => false ) ); if ( ! empty( $activities['activities'] ) ) : ?><div class="sd-profile-activity-list"><?php foreach ( $activities['activities'] as $activity ) : ?><article><time><?php echo esc_html( $activity->date_recorded ); ?></time><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $activity->content ), 30 ) ); ?></p></article><?php endforeach; ?></div><?php else : ?><p class="sd-muted"><?php esc_html_e( 'No public activity to show.', 'social-discovery' ); ?></p><?php endif; else : ?><p class="sd-muted"><?php esc_html_e( 'Public activity is available when BuddyPress is active.', 'social-discovery' ); ?></p><?php endif; ?></section>
